local KTool = CS.Engine.Lib.KTool
local StoreUtils = import('Game.UI.Store.StoreUtils')
--- from: Assets/BundleResources/Prefabs/ResidentEvent/ResidentMonthlyCardDialog.prefab > name: ResidentMonthlyCardDialog
---@class StoreMonthCard
---@field Env                           	StoreMonthCard                          
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field RigthPanel                    	Engine.Modules.LuaBehaviour             	@ 0    
---@field Root                          	UnityEngine.RectTransform               	@ 1    
---@field LeftPanel                     	Engine.Modules.LuaBehaviour             	@ 2    
local StoreMonthCard = Class('StoreMonthCard')
local MONTH_CARD_TYPE = {
    COMMON = 1  ,  -- 普通月卡
    LIFELONG = 2 , -- 终身月卡
}
function StoreMonthCard:__init()
    self.isInitialized = false
end

function StoreMonthCard:__delete()
    if self.__EventSdkEvent  then
        Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.__EventSdkEvent)
        self.__EventSdkEvent = nil   
    end
    self.isInitialized = false
end

function StoreMonthCard:AddListener()
    if not self.isInitialized then
        self.isInitialized = true
        self._refreshHandler = Bind(self, self.RefreshSelf)
        self._updateHandler = Bind(self, self.Refresh)
        self.__EventSdkEvent = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))
        Events.AddListener(Constants.EventNames.OnMonthCardRefresh, self._refreshHandler)
        Events.AddListener(Constants.EventNames.OnMonthCardExpired, self._refreshHandler)
        Events.AddListener(Constants.EventNames.OnMonthCardUpdate, self._updateHandler)
    end
end

function StoreMonthCard:Awake()
    ---重要： cn国服把最下方tip去除不显示，不要合代码去掉了
    CfUtils.SetActive(self.RigthPanel.transform.parent:Find("TxtTips"), false)
    self:AddListener()
end
function StoreMonthCard:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        local productId = parameters.productId
        local comp = StoreUtils.GetStoreComp()
        local MonthCardInfo = comp.MonthCardInfo
        local isHave =  false 
        local monthCardId = 0
        for i, v in pairs(MonthCardInfo) do
            if checkInt(v.monthCardId) > 0 then
               if v.channelProductId == productId  then
                    isHave  = true 
                    monthCardId = v.monthCardId
                    break
               end
            end
        end 

        if isHave then
            self:Refresh()
            ---@type MonthCardVo
            local vo =  CfUtils.GetCfVo(AutoIds.IdSetting602, "MonthCardVo" , monthCardId)
            if vo.type == MONTH_CARD_TYPE.COMMON then
                xRecord.af_internal('pay_monthly_card')
            else 
                xRecord.af_internal('pay_forever_card')
            end 
        end
    end
end
function StoreMonthCard:Start()
end

function StoreMonthCard:Refresh()
    self:AddListener()
    GameUtils.Request(Interfaces.StoreMonthCardHome, {}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            xRecord.record('7-005')
            local isActivite = KTool.IsActive(self.Root.gameObject)
            if not isActivite then
                KTool.SetActive(self.Root.gameObject , true) 
            end
            local comp = StoreUtils.GetStoreComp()
            comp:RefreshMonthCardInfo(response.data.monthCard)
        end
    end)
end

function StoreMonthCard:RefreshSelf()
    local comp = StoreUtils.GetStoreComp()
    local MonthCardInfo = comp.MonthCardInfo
    for i, v in pairs(MonthCardInfo) do
        if checkInt(v.monthCardId) > 0 then
            ---@type MonthCardVo
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting602,"MonthCardVo",v.monthCardId)
            local Env = nil
            if vo.type == MONTH_CARD_TYPE.COMMON then
                ---@type StoreItemCard
                --Env = self.LeftPanel.Env
                Env = CfUtils.GetLuaScr(self.LeftPanel, "Game.UI.Store.StoreItemCard")
                if isNotNull(Env) then
                    Env:RefreshCard(v.monthCardId)
                end
            elseif vo.type == MONTH_CARD_TYPE.LIFELONG then
                --Env = self.RigthPanel.Env
                Env = CfUtils.GetLuaScr(self.RigthPanel, "Game.UI.Store.StoreItemCard")
                if isNotNull(Env) then
                    Env:RefreshCard(v.monthCardId)
                end
            end
        end
    end
end

function StoreMonthCard:OnDestroy()
    Events.RemoveListener(Constants.EventNames.OnMonthCardRefresh, self._refreshHandler)
    Events.RemoveListener(Constants.EventNames.OnMonthCardExpired, self._refreshHandler)
    Events.RemoveListener(Constants.EventNames.OnMonthCardUpdate, self._updateHandler)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return StoreMonthCard